package br.org.pianolivre;

import android.app.AlertDialog;
import android.graphics.Color;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import android.os.Handler;
import java.io.File;import java.io.IOException;
import java.util.*;

/** Native responsive entry point and one-take workflow for Laboratory → Creation. */
final class MusicCreationScreen extends LinearLayout {
 private final MainActivity a;private final Runnable back;private final LinearLayout body,bar;private final ScrollView scroll;private int listScrollY;
 private CreationProjectStore store;private MidiTakeRecorder take;private CreationJournal journal;private int journaledEvents,journaledSegments,takeProfileId;private long takeCreatedAt;private String selectedId;private String page="home";private final MidiTakePlayer player;private TextView playbackStatus;private boolean ignoreSilence=true,journalsScanned;
 private CreationProjectStore.Filter filter=CreationProjectStore.Filter.ALL;private String query="";private int sortMode=0;
 private final int navy=0xff101C31,ink=0xff172A44,blue=0xff286BCB,muted=0xff57708A;
 MusicCreationScreen(MainActivity activity,Runnable goBack){super(activity);a=activity;back=goBack;setOrientation(VERTICAL);setVisibility(GONE);setBackgroundColor(0xffF7F9FC);
  player=new MidiTakePlayer(new MidiTakePlayer.Sink(){public boolean available(){return a.midiConnection.snapshot().canSend;}public boolean send(byte[] data){return a.midiConnection.send(data);}public void silence(){a.midiConnection.silence();}},(state,pos,duration)->post(()->{if(playbackStatus!=null)playbackStatus.setText(state+" · "+String.format(Locale.ROOT,"%.1f / %.1f s",pos/1e9,duration/1e9));}),command->a.handler.post(command));
  bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(8),dp(3),dp(8),dp(3));bar.setBackgroundColor(navy);addView(bar,new LayoutParams(-1,dp(50)));
  body=new LinearLayout(a);body.setOrientation(VERTICAL);body.setPadding(dp(16),dp(12),dp(16),dp(16));scroll=new ScrollView(a);scroll.setFillViewport(true);scroll.addView(body);addView(scroll,new LayoutParams(-1,0,1));
  try{store=new CreationProjectStore(a.getFilesDir());}catch(IOException ex){a.message("Não foi possível abrir Minhas Criações: "+ex.getMessage());}
  showHome();
 }
 private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size,boolean bold){TextView t=new TextView(a);t.setText(s);t.setTextSize(size);t.setTextColor(ink);if(bold)t.setTypeface(null,android.graphics.Typeface.BOLD);return t;}
 private Button button(String s,boolean primary,Runnable action){Button b=new Button(a);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(primary?Color.WHITE:ink);b.setMinHeight(dp(48));b.setOnClickListener(v->action.run());b.setBackgroundColor(primary?blue:0xffEAF0F7);return b;}
 private void header(String title,Runnable returnAction){bar.removeAllViews();Button b=button("← Voltar",false,returnAction);bar.addView(b,new LayoutParams(dp(110),-1));TextView t=text(title,18,true);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER_VERTICAL);bar.addView(t,new LayoutParams(0,-1,1));}
 private void base(String title,Runnable returnAction){header(title,returnAction);body.removeAllViews();}
 void enter(){setVisibility(VISIBLE);if(!journalsScanned){journalsScanned=true;recoverJournals();}showHome();}
 boolean hasUnsavedTake(){return take!=null&&(take.state()==MidiTakeRecorder.State.RECORDING||take.state()==MidiTakeRecorder.State.PAUSED||take.state()==MidiTakeRecorder.State.REVIEW||take.state()==MidiTakeRecorder.State.INTERRUPTED);}
 void requestLeave(){player.stop();if("details".equals(page)){showList();return;}if("list".equals(page)){showHome();return;}if("recording".equals(page)){if(!hasUnsavedTake()){showHome();return;}new AlertDialog.Builder(a).setTitle("Gravação não salva").setMessage("Salve o trecho recuperável antes de sair?")
  .setPositiveButton("Salvar trecho",(d,w)->{if(saveRecoverable("Trecho recuperável"))showHome();else a.message("O trecho continua nesta tela e no diário local; tente salvar novamente.");}).setNegativeButton("Descartar",(d,w)->confirmDiscard()).setNeutralButton("Continuar",null).show();return;}back.run();}
 void onBackground(){player.stop();if(take!=null&&(take.state()==MidiTakeRecorder.State.RECORDING||take.state()==MidiTakeRecorder.State.PAUSED||take.state()==MidiTakeRecorder.State.REVIEW||take.state()==MidiTakeRecorder.State.INTERRUPTED)){if(saveRecoverable("Gravação interrompida"))showHome();}}
 void onMidi(int status,int a1,int a2,long timeNs,long epoch,long androidTime,int source){if(take!=null&&player.state()!=MidiTakePlayer.State.PLAYING&&take.accept(status,a1,a2,timeNs,epoch,androidTime,source))try{persistJournalDelta();}catch(IOException ex){android.util.Log.e("PianoLivreCreation","Falha no journal incremental",ex);take.interrupt("Falha de persistência");if(saveRecoverable("Trecho recuperável"))showHome();else a.message("Falha ao confirmar o trecho. Ele permanece nesta tela; não saia até salvá-lo.");}}
 void onConnectionLost(){player.stop();if(take!=null&&(take.state()==MidiTakeRecorder.State.RECORDING||take.state()==MidiTakeRecorder.State.PAUSED||take.state()==MidiTakeRecorder.State.REVIEW||take.state()==MidiTakeRecorder.State.INTERRUPTED)){if(saveRecoverable("Gravação interrompida"))showHome();}}
 private String profileName(){for(LocalProfiles.Profile p:a.profileStore().list())if(p.id==a.user)return p.name;return "Perfil "+a.user;}
 private String midiState(){MidiConnection.Snapshot s=a.midiConnection.snapshot();return "MIDI · Entrada: "+(s.canReceive?"conectada":"indisponível")+" · Saída: "+(s.canSend?"conectada":"indisponível");}
 private void showHome(){page="home";player.stop();take=null;selectedId=null;base("Criação Musical",this::requestLeave);body.addView(text("Perfil ativo · "+profileName(),17,true));body.addView(text(midiState(),14,false));
  Button record=button("＋  Nova gravação",true,()->showRecorder());body.addView(record,new LayoutParams(-1,dp(58)));
  Button list=button("Minhas Criações",false,()->showList());body.addView(list,new LayoutParams(-1,dp(54)));
  body.addView(text("Recentes",18,true));addProjects(CreationProjectStore.Filter.ALL,3);
  if(body.getChildCount()<=4)body.addView(text("Suas composições aparecerão aqui. Conecte seu piano para começar uma gravação.",15,false));
 }
 private void showRecorder(){page="recording";base("Nova gravação",this::requestLeave);take=new MidiTakeRecorder();takeCreatedAt=System.currentTimeMillis();TextView info=text("Perfil · "+profileName()+"\n"+midiState(),15,false);body.addView(info);
  TextView state=text("Pronta para gravar · uma tomada por composição",18,true);body.addView(state);
  TextView count=text("Eventos MIDI: 0",16,false);body.addView(count);
  Button start=button("●  Gravar",true,()->{if(hasUnsavedTake()){a.message("Pare e salve ou descarte a tomada atual antes de gravar novamente.");return;}MidiConnection.Snapshot s=a.midiConnection.snapshot();if(!s.canReceive){a.selectMidi();return;}try{take=new MidiTakeRecorder();takeProfileId=a.user;takeCreatedAt=System.currentTimeMillis();long startNs=android.os.SystemClock.elapsedRealtimeNanos();take.start(a.midiInputEpoch(),startNs);String session=UUID.randomUUID().toString();journal=new CreationJournal(a.getFilesDir(),session,"Gravação recuperável",takeProfileId,takeCreatedAt,startNs);journaledEvents=journaledSegments=0;state.setText("Gravando… toque no piano conectado");}catch(IOException ex){take=null;a.message("Não foi possível iniciar com recuperação segura: "+ex.getMessage());}});body.addView(start,new LayoutParams(-1,dp(54)));
  Button pause=button("Pausar",false,()->{if(player.state()==MidiTakePlayer.State.PLAYING){player.pause();return;}if(take!=null&&take.state()==MidiTakeRecorder.State.RECORDING){try{take.pause(android.os.SystemClock.elapsedRealtimeNanos());persistJournalDelta();journal.flush();state.setText("Pausada · "+take.eventCount()+" eventos recebidos");}catch(IOException ex){a.message("O diário não foi confirmado; a gravação foi interrompida com segurança.");take.interrupt("Falha ao confirmar pausa");if(saveRecoverable("Trecho recuperável"))showHome();}}});body.addView(pause,new LayoutParams(-1,dp(48)));
  Button resume=button("Continuar",false,()->{if(player.state()==MidiTakePlayer.State.PAUSED){player.resume();return;}if(take!=null&&take.state()==MidiTakeRecorder.State.PAUSED){long now=android.os.SystemClock.elapsedRealtimeNanos();if(journal==null||!journal.beginSegment(now)){a.message("Não foi possível iniciar um segmento seguro.");return;}take.resume(now,a.midiInputEpoch());state.setText(take.state()==MidiTakeRecorder.State.RECORDING?"Gravando…":"Trecho recuperável · conexão mudou");}});body.addView(resume,new LayoutParams(-1,dp(48)));
  Button save=button("Salvar composição",true,()->saveTake());save.setEnabled(false);
  Button discard=button("Descartar…",false,()->confirmDiscard());discard.setEnabled(false);
  Button stop=button("■  Parar",false,()->{player.stop();if(take!=null&&(take.state()==MidiTakeRecorder.State.RECORDING||take.state()==MidiTakeRecorder.State.PAUSED)){take.stop(android.os.SystemClock.elapsedRealtimeNanos());try{persistJournalDelta();journal.flush();}catch(IOException ex){a.message("A revisão continua local, mas o diário não foi confirmado; salve o trecho recuperável.");}state.setText("Revisão · "+take.eventCount()+" eventos · "+(take.durationNs()/1_000_000_000.0)+" s");count.setText("Eventos MIDI: "+take.eventCount());save.setEnabled(take.eventCount()>0);discard.setEnabled(true);}});body.addView(stop,new LayoutParams(-1,dp(48)));
  body.addView(save,new LayoutParams(-1,dp(52)));body.addView(discard,new LayoutParams(-1,dp(48)));
  Button preview=button("Reproduzir gravação",false,()->{if(take==null||take.state()!=MidiTakeRecorder.State.REVIEW)return;if(!a.midiConnection.snapshot().canSend){a.message("Conecte uma saída MIDI funcional para reproduzir.");return;}player.play(new CreationProjectStore.Project(UUID.randomUUID().toString(),"Nova composição",takeProfileId,takeCreatedAt,takeCreatedAt,take.durationNs(),false,false,take.events(),take.segments()),false);});
  body.addView(preview,new LayoutParams(-1,dp(48)));
  Runnable ticker=new Runnable(){public void run(){if(!"recording".equals(page)||take==null)return;MidiTakeRecorder.State current=take.state();boolean recording=current==MidiTakeRecorder.State.RECORDING,paused=current==MidiTakeRecorder.State.PAUSED,review=current==MidiTakeRecorder.State.REVIEW;
   start.setEnabled(current==MidiTakeRecorder.State.READY);pause.setEnabled(recording||player.state()==MidiTakePlayer.State.PLAYING);resume.setEnabled(paused||player.state()==MidiTakePlayer.State.PAUSED);stop.setEnabled(recording||paused||player.state()!=MidiTakePlayer.State.STOPPED);save.setEnabled(review&&take.eventCount()>0);discard.setEnabled(current!=MidiTakeRecorder.State.READY);preview.setEnabled(review);count.setText(String.format(Locale.getDefault(),"%.1f s · %d eventos MIDI",take.elapsedNs(android.os.SystemClock.elapsedRealtimeNanos())/1e9,take.eventCount()));a.handler.postDelayed(this,100);}};ticker.run();

 }
 private void saveTake(){if(take==null||take.state()!=MidiTakeRecorder.State.REVIEW){a.message("Pare a gravação antes de salvar.");return;}EditText title=new EditText(a);title.setSingleLine(true);title.setText("Nova composição");new AlertDialog.Builder(a).setTitle("Salvar composição").setView(title).setPositiveButton("Salvar",(d,w)->{try{try{persistJournalDelta();journal.flush();}catch(Exception journalError){android.util.Log.e("PianoLivreCreation","Journal incompleto; commit final usa gravação atômica integral",journalError);}store.save(journal.sessionId(),title.getText().toString().trim(),takeProfileId,takeCreatedAt,take.durationNs(),take.events(),take.segments());take.markSaved();CreationJournal old=journal;journal=null;take=null;showHome();try{old.deleteAfterCommit();}catch(IOException cleanup){old.close();android.util.Log.w("PianoLivreCreation","Journal já salvo; limpeza será refeita na retomada",cleanup);}}catch(Exception ex){a.message("A composição não foi salva; o diário permanece recuperável: "+ex.getMessage());}}).setNegativeButton("Cancelar",null).show();}
 private boolean saveRecoverable(String title){if(take==null)return true;take.interrupt(android.os.SystemClock.elapsedRealtimeNanos(),"Interrupção do app/conexão");try{persistJournalDelta();if(journal!=null)journal.flush();}catch(Exception journalError){android.util.Log.e("PianoLivreCreation","Journal parcial; tentando commit integral do trecho em memória",journalError);}try{if(take.eventCount()>0){if(store==null)throw new IOException("Biblioteca local indisponível");if(journal!=null)store.saveRecoverable(journal.sessionId(),title,takeProfileId,takeCreatedAt,take.durationNs(),take.events(),take.segments());else store.saveRecoverable(title,takeProfileId,takeCreatedAt,take.durationNs(),take.events(),take.segments());}CreationJournal old=journal;journal=null;take=null;if(old!=null)try{old.deleteAfterCommit();}catch(IOException cleanup){old.close();android.util.Log.w("PianoLivreCreation","Journal recuperado; limpeza pendente",cleanup);}return true;}catch(Exception ex){android.util.Log.e("PianoLivreCreation","Falha ao persistir trecho recuperável",ex);return false;}}
 private void persistJournalDelta()throws IOException{if(journal==null||take==null)return;for(MidiTakeRecorder.Event e:take.eventsSince(journaledEvents)){if(!journal.append(e))throw new IOException("Fila do diário indisponível");journaledEvents++;}for(MidiTakeRecorder.Segment s:take.segmentsSince(journaledSegments)){if(!journal.append(s))throw new IOException("Fila do diário indisponível");journaledSegments++;}}
 private void recoverJournals(){if(store==null)return;File dir=new File(a.getFilesDir(),"creation-journals");File[] pending=dir.listFiles((d,n)->n.endsWith(".journal"));if(pending==null)return;for(File f:pending){try{CreationJournal.Recovery r=CreationJournal.read(f);if(r.events.isEmpty()){continue;}store.saveRecoverable(r.sessionId,r.title,r.profileId,r.createdAt,segmentDuration(r.segments),r.events,r.segments);if(!f.delete())android.util.Log.w("PianoLivreCreation","Journal promovido; arquivo duplicado será conferido novamente");if(r.truncated)android.util.Log.w("PianoLivreCreation","Recuperado prefixo íntegro de journal truncado");}catch(Exception ex){android.util.Log.e("PianoLivreCreation","Journal preservado para diagnóstico; não foi promovido",ex);}}}
 void prepareBackup()throws IOException{if(take!=null&&(take.state()==MidiTakeRecorder.State.RECORDING||take.state()==MidiTakeRecorder.State.PAUSED||take.state()==MidiTakeRecorder.State.REVIEW))throw new IOException("Salve ou interrompa a gravação antes do backup");recoverJournals();File dir=new File(a.getFilesDir(),"creation-journals");File[] remaining=dir.listFiles((d,n)->n.endsWith(".journal"));if(remaining!=null&&remaining.length>0)throw new IOException("Há trecho recuperável ainda não validado; o backup não foi iniciado");}
 private static long segmentDuration(List<MidiTakeRecorder.Segment> segments){long total=0;for(MidiTakeRecorder.Segment s:segments)total+=s.endNs-s.startNs;return total;}
 private void confirmDiscard(){if(take==null)return;new AlertDialog.Builder(a).setTitle("Descartar gravação?").setMessage("Os eventos desta tomada serão removidos.").setPositiveButton("Descartar",(d,w)->{try{if(journal!=null){journal.discardAndDelete();journal=null;}take.discard();take=null;showHome();}catch(IOException ex){a.message("Não foi possível concluir o descarte: "+ex.getMessage());}}).setNegativeButton("Continuar",null).show();}
 private void showList(){player.stop();page="list";base("Minhas Criações",this::showHome);EditText search=new EditText(a);search.setSingleLine(true);search.setHint("Buscar composição…");search.setText(query);body.addView(search,new LayoutParams(-1,dp(48)));Spinner filters=new Spinner(a);String[] names={"Todas","Salvas","Recuperáveis","Lixeira"};filters.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,names));filters.setSelection(filter.ordinal());body.addView(filters,new LayoutParams(-1,dp(48)));Spinner sorting=new Spinner(a);String[] sortNames={"Mais recentes","Mais antigos","Nome A–Z","Nome Z–A","Maior duração","Menor duração"};sorting.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,sortNames));sorting.setSelection(sortMode);body.addView(sorting,new LayoutParams(-1,dp(48)));LinearLayout results=new LinearLayout(a);results.setOrientation(VERTICAL);body.addView(results,new LayoutParams(-1,-2));Runnable refresh=()->{query=search.getText().toString();filter=CreationProjectStore.Filter.values()[filters.getSelectedItemPosition()];sortMode=sorting.getSelectedItemPosition();results.removeAllViews();populate(results,filter,query);};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){refresh.run();}public void afterTextChanged(android.text.Editable e){}});android.widget.AdapterView.OnItemSelectedListener changed=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){refresh.run();}};filters.setOnItemSelectedListener(changed);sorting.setOnItemSelectedListener(changed);refresh.run();scroll.post(()->scroll.scrollTo(0,listScrollY));}
 private void addProjects(CreationProjectStore.Filter f,int limit){if(store==null)return;try{List<CreationProjectStore.Project> ps=store.list(a.user,f,"",null);for(int i=0;i<Math.min(limit,ps.size());i++)addProjectRow(body,ps.get(i));}catch(IOException ex){body.addView(text("Não foi possível ler os projetos salvos.",14,false));}}
 private void populate(LinearLayout target,CreationProjectStore.Filter f,String q){try{Comparator<CreationProjectStore.Project> cmp;switch(sortMode){case 1:cmp=Comparator.comparingLong((CreationProjectStore.Project p)->p.editedAt).thenComparing(p->p.id);break;case 2:cmp=Comparator.comparing(p->p.title.toLowerCase(Locale.ROOT));break;case 3:cmp=Comparator.comparing((CreationProjectStore.Project p)->p.title.toLowerCase(Locale.ROOT)).reversed();break;case 4:cmp=Comparator.comparingLong((CreationProjectStore.Project p)->p.durationNs).reversed();break;case 5:cmp=Comparator.comparingLong((CreationProjectStore.Project p)->p.durationNs);break;default:cmp=null;}if(cmp!=null)cmp=cmp.thenComparing(p->p.id);List<CreationProjectStore.Project> ps=store.list(a.user,f,q,cmp);if(ps.isEmpty()){target.addView(text("Nenhuma composição encontrada.",15,false));return;}for(CreationProjectStore.Project p:ps)addProjectRow(target,p);}catch(IOException ex){target.addView(text("Não foi possível ler Minhas Criações.",15,false));}}
 private void addProjectRow(LinearLayout target,CreationProjectStore.Project p){Button row=button(p.title+"\n"+new Date(p.createdAt)+" · "+(p.durationNs/1_000_000_000.0)+" s"+(p.recoverable?" · Recuperável":p.trash?" · Lixeira":""),false,()->showDetails(p.id));row.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);target.addView(row,new LayoutParams(-1,dp(68)));}
 private void showDetails(String id){page="details";try{listScrollY=scroll.getScrollY();CreationProjectStore.Project p=store.get(id);selectedId=id;base(p.title,this::showList);body.addView(text("Criada · "+new Date(p.createdAt)+"\nDuração · "+(p.durationNs/1_000_000_000.0)+" s\nEventos · "+p.events.size()+"\nPerfil · "+profileName(),15,false));
  body.addView(button("Renomear",false,()->rename(p)),new LayoutParams(-1,dp(48)));
  if(p.recoverable&&!p.trash)body.addView(button("Revisar e salvar trecho recuperado",true,()->mutate(()->store.finalizeRecovery(id,System.currentTimeMillis()))),new LayoutParams(-1,dp(52)));
  if(!p.trash)body.addView(button("Exportar MIDI (.mid)",false,()->a.exportCreationMidi(id,p.title)),new LayoutParams(-1,dp(48)));
  if(!p.trash){CheckBox trim=new CheckBox(a);trim.setText("Ignorar silêncio inicial e final na reprodução");trim.setChecked(ignoreSilence);trim.setOnCheckedChangeListener((v,checked)->ignoreSilence=checked);body.addView(trim,new LayoutParams(-1,-2));playbackStatus=text("Parado",14,false);body.addView(playbackStatus,new LayoutParams(-1,dp(40)));
   Button play=button("▶ Reproduzir no piano",true,()->{if(!a.midiConnection.snapshot().canSend){a.message("Conecte uma saída MIDI funcional para reproduzir no instrumento.");return;}try{player.play(store.get(id),ignoreSilence);}catch(IOException ex){a.message("Não foi possível reproduzir: "+ex.getMessage());}});body.addView(play,new LayoutParams(-1,dp(50)));
   body.addView(button("Pausar",false,()->player.pause()),new LayoutParams(-1,dp(46)));body.addView(button("Continuar",false,()->player.resume()),new LayoutParams(-1,dp(46)));body.addView(button("Parar",false,()->player.stop()),new LayoutParams(-1,dp(46)));}
  if(p.trash){body.addView(button("Restaurar",false,()->mutate(()->store.restore(id,System.currentTimeMillis()))),new LayoutParams(-1,dp(48)));body.addView(button("Excluir definitivamente…",false,()->new AlertDialog.Builder(a).setTitle("Excluir definitivamente?").setMessage("Esta ação não pode ser desfeita.").setPositiveButton("Excluir",(d,w)->mutate(()->store.deletePermanently(id))).setNegativeButton("Cancelar",null).show()),new LayoutParams(-1,dp(48)));}
  else body.addView(button("Mover para Lixeira",false,()->mutate(()->store.moveToTrash(id,System.currentTimeMillis()))),new LayoutParams(-1,dp(48)));
 }catch(Exception ex){a.message("Não foi possível abrir a composição: "+ex.getMessage());showList();}}
 private interface Mutation{void run()throws Exception;}private void mutate(Mutation m){try{m.run();showList();}catch(Exception ex){a.message("A alteração não foi aplicada: "+ex.getMessage());}}
 private void rename(CreationProjectStore.Project p){EditText input=new EditText(a);input.setSingleLine(true);input.setText(p.title);new AlertDialog.Builder(a).setTitle("Renomear composição").setView(input).setPositiveButton("Salvar",(d,w)->mutate(()->store.rename(p.id,input.getText().toString().trim(),System.currentTimeMillis()))).setNegativeButton("Cancelar",null).show();}
 void close(){player.close();}
}
